from itertools import combinations


def _routes(minimum_duration, exact_coupons):
    def solve(data):
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit.get(source, 0)
        budget = data["coupons"]
        start = (source, initial_mask, 0)
        best = {start: data["start"]}
        queue = [(data["start"], source, initial_mask, 0)]

        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != time:
                continue
            if node == data["target"] and mask == full and (not exact_coupons or used == budget):
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < budget:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | bit.get(nxt, 0)
                    next_state = (nxt, next_mask, next_used)
                    if arrival < best.get(next_state, float("inf")):
                        best[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    def rounded(numerator):
        if data["rounding"] == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    roots = [(name, bounds[0], bounds[1], None)
             for name, bounds in data.get("roots", {}).items()]
    best_result = None
    best_vector = None
    names = sorted(packages, reverse=True)

    def search(chosen, constraints, edges, pending):
        nonlocal best_result, best_vector
        if not pending:
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_result = dict(chosen)
            return

        name, low, high, parent = pending[0]
        rest = pending[1:]
        constraints = {key: list(value) for key, value in constraints.items()}
        constraints.setdefault(name, []).append((low, high))
        edges = {key: set(value) for key, value in edges.items()}
        if parent is not None:
            edges.setdefault(parent, set()).add(name)
            # Reject an edge that closes a directed cycle.
            todo, visited = [name], set()
            while todo:
                current = todo.pop()
                if current == parent:
                    return
                if current not in visited:
                    visited.add(current)
                    todo.extend(edges.get(current, ()))

        def satisfies(version):
            return all(lo <= version <= hi for lo, hi in constraints[name])

        if name in chosen:
            if satisfies(chosen[name]):
                search(chosen, constraints, edges, rest)
            return

        blocked = set(data.get("blocked", {}).get(name, []))
        pin = data.get("pins", {}).get(name)
        rows = sorted(packages.get(name, []), key=lambda row: row["version"])
        for row in rows:
            version = row["version"]
            if version in blocked or (pin is not None and version != pin) or not satisfies(version):
                continue
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_pending = list(rest)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                next_pending.append((dep["name"], dep["min"], dep["max"], name))
            search(next_chosen, constraints, edges, next_pending)

    search({}, {}, {}, roots)
    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


def _quotas(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}) or len(mandatory) > k:
        return {"error": "impossible"}

    best_ids = None
    best_value = None
    for selection in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in selection))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selection:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not (low <= counts.get(group, 0) <= high)
               for group, (low, high) in data.get("quotas", {}).items()):
            continue
        ordered = sorted(selection, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in selection)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


